using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;
public static class VerifyCopingOriginal
{
 const string D="Assets/M/CodexTemp/ElevatorCoping_20261030~/";static ElevatorLesson l;static ElevatorDesktopControls c;static ElevatorScenarioDirector s;static List<object> checks=new List<object>();static int passed;
 static void Check(bool ok,string name){checks.Add(new{name,passed=ok});if(!ok)throw new Exception(name);passed++;}
 static async Task Mouse(bool down=false){var v=new MouseState{position=new Vector2(Screen.width*.5f,Screen.height*.5f)};if(down)v=v.WithButton(MouseButton.Left,true);InputSystem.QueueStateEvent(UnityEngine.InputSystem.Mouse.current,v);await Task.Delay(90);}
 static async Task Aim(Vector3 p){var r=Quaternion.LookRotation(p-l.playerCamera.transform.position).eulerAngles;c.SetLookAngles(r.y,Mathf.DeltaAngle(0,r.x));await Mouse();await Task.Delay(90);}
 static async Task Click(){await Mouse(true);await Mouse();}
 static async Task Physical(string name){var o=l.GetComponentsInChildren<ElevatorObservation>(true).First(x=>x.name==name);await Aim(o.transform.position);Check(c.HoverTargetName==name,"Centre ray selects "+name);await Click();}
 static async Task Shot(string name){await Task.Delay(100);ScreenCapture.CaptureScreenshot(D+name+".png");await Task.Delay(160);}
 static void Clear(){l.presentation.space.overlay.Advance(2);}
 static void Teleport(Vector3 p,float yaw){var m=c.movement;m.Controller.enabled=false;m.transform.position=p-Vector3.up*m.FeetOffset;m.Controller.enabled=true;m.ResetVerticalMotion();c.SetLookAngles(yaw,0);Physics.SyncTransforms();}
 static void PureFlow()
 {
  foreach(bool jump in new[]{false,true})
  {
   var f=new ElevatorFlow(l.settings);f.Continue();f.Tick(7);f.SelectDestination();f.Continue();if(jump)f.UnsafeProposal();else f.ChooseSafe();Check(f.Step==(jump?ElevatorStep.Jump:ElevatorStep.Travel),"Chosen branch begins "+(jump?"friend jump":"no jump travel"));Check(f.JumpCount==(jump?1:0),"Jump count is branch specific");f.Tick(5);Check(f.Step==ElevatorStep.Stopped,"Both branches reach equipment fault");f.Tick(2);f.RequestIntercom();f.Tick(4);f.ReportSituation();Check(f.SituationReported&&!f.IdentityFound,"Situation is reported before identity lookup");f.FindIdentity();f.ReportLocation();f.FollowAdvice();f.Reassure();Check(f.Step==ElevatorStep.WaitingFade,"Completed coping enters faded wait");f.Tick(5);Check(f.Step==ElevatorStep.Rescue&&!f.ReadyToExit,"Wait fade leads to staff arrival");f.Tick(4);f.Continue();f.Tick(5);f.Continue();f.Tick(4);f.Continue();f.Tick(7);Check(f.Step==ElevatorStep.Complete,"Branch completes staff-guided return");
  }
 }
 public static async Task<string> Main()
 {
  for(int i=0;i<100;i++){l=Object.FindFirstObjectByType<ElevatorLesson>();if(Application.isPlaying&&l&&l.Flow!=null)break;await Task.Delay(100);}c=Object.FindFirstObjectByType<ElevatorDesktopControls>();s=l.scenario;checks.Clear();passed=0;int frame=Time.frameCount;string error=null;
  var old=InputSystem.settings;var temp=Object.Instantiate(old);temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temp;
  var hardware=UnityEngine.InputSystem.Mouse.current;bool enabled=hardware!=null&&hardware.enabled;if(enabled)InputSystem.DisableDevice(hardware);var mouse=InputSystem.AddDevice<UnityEngine.InputSystem.Mouse>("CopingQAMouse");mouse.MakeCurrent();GameObject blocker=null;Material blockerMaterial=null;
  try
  {
   Check(Application.isPlaying&&l.Flow!=null&&!s.objectGuidedScene,"Original scene is running");PureFlow();l.Restart();await Task.Delay(200);Clear();
   Check(!Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include,FindObjectsSortMode.None).Any(v=>v.renderMode!=RenderMode.WorldSpace),"Every scene canvas is world space");Check(!l.view.spatial.hud.gameObject.activeInHierarchy,"Screen HUD is removed from play");
   var up=l.transform.Find("SportsCentre_Interactions/3F_Lobby_Up_Unavailable");await Aim(up.position);Check(c.HoverTargetName!="3F_Lobby_Call"&&l.Flow.Step==ElevatorStep.Lobby,"Upper call button does not select the down call");await Click();Check(l.Flow.Step==ElevatorStep.Lobby,"Upper call click cannot board");
   var down=l.transform.Find("SportsCentre_Interactions/3F_Lobby_Call");await Aim(down.position);var target=down.GetComponent<ElevatorObservation>();Check(target.shapeHighlight.shells.All(r=>r.transform.position.y<9.20f),"Only the lower call-button geometry highlights");
   var hint=s.hints.First(h=>h.observation==target);Check(hint.group.alpha>.99f,"Object hint appears beside lower call button");await Shot("01_DownCallAndFixedHint");
   c.enabled=false;target.Hover(true);await Task.Delay(100);var anchor=hint.transform.position;var oldPosition=c.xrOrigin.position;Teleport(c.movement.FeetPosition+Vector3.left*.35f,0);await Task.Delay(120);Check(Vector3.Distance(hint.transform.position,anchor)<.001f,"Object hint position stays fixed when player moves");Check(Vector3.Dot(hint.transform.forward,(hint.transform.position-l.playerCamera.transform.position).normalized)>.999f,"Fixed hint faces the player");Teleport(oldPosition,0);c.enabled=true;
   Teleport(new Vector3(5.25f,7.98f,-2.65f),0);for(int i=0;i<100;i++)c.movement.Move(Vector2.up,.02f,false);Check(c.movement.FeetPosition.z< -2.28f,"Transparent stair wall blocks walking out");Teleport(new Vector3(-.6f,7.98f,-4.7f),180);for(int i=0;i<100;i++)c.movement.Move(Vector2.up,.02f,false);Check(c.movement.FeetPosition.z> -5.4f,"Transparent terrace wall blocks leaving the floor");
   l.Restart();Clear();await Physical("3F_Lobby_Call");Check(target.feedback.PressCount==1,"Lower call has button press feedback");await Task.Delay(1400);var direction=(new Vector3(-1.8f,7.92f,3.6f)-l.presentation.space.sportsCentre.friendLobby).normalized;Check(Vector3.Dot(l.friend.TransformDirection(Vector3.back),direction)>.9f,"Friend faces the actual boarding walking direction");Check(l.GetComponent<ElevatorCharacterPerformance>().WalkPhase>.2f,"Friend leg gait advances with movement");await Shot("02_BoardingWalk");await Task.Delay(5200);Clear();Check(l.Flow.Step==ElevatorStep.Boarding,"Boarding finishes normally");
   var floor=l.transform.Find("SportsCentre_Interactions/3F_Side_Floor01").GetComponent<ElevatorObservation>();var before=floor.feedback.movingPart.localPosition;await Physical(floor.name);Check(l.Flow.DestinationSelected&&floor.feedback.PressCount==1,"Floor button selects destination and confirms press");await Task.Delay(550);Check(Vector3.Distance(floor.feedback.movingPart.localPosition,before)<.0001f,"Pressed floor button returns to its rest position");
   l.Continue();Clear();Check(l.view.ChoiceButtons.Count==3,"Original scene retains dialogue choices");await Aim(l.view.dialoguePanel.position);blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.GetComponent<Collider>().enabled=false;blocker.transform.SetPositionAndRotation(l.playerCamera.transform.position+l.playerCamera.transform.forward*.18f,l.playerCamera.transform.rotation);blocker.transform.localScale=new Vector3(5,5,.04f);blockerMaterial=new Material(Shader.Find("Universal Render Pipeline/Unlit"));blockerMaterial.color=new Color(.17f,.1f,.21f);blocker.GetComponent<Renderer>().sharedMaterial=blockerMaterial;
   await Task.Delay(150);Check(l.view.GetComponentsInChildren<TMPro.TMP_Text>().All(t=>t.fontSharedMaterial.shader.name.Contains("Overlay")),"World dialogue text uses geometry-independent depth");await Shot("03_WorldUIThroughOccluder");blocker.GetComponent<Collider>().enabled=true;
   await Aim(l.view.ChoiceButtons[1].transform.position);Check(c.HoverTargetName==l.view.ChoiceButtons[1].name,"Visible world UI remains selectable through geometry");await Click();Object.DestroyImmediate(blocker);blocker=null;Object.DestroyImmediate(blockerMaterial);blockerMaterial=null;Check(l.Flow.Step==ElevatorStep.Jump&&l.Flow.JumpCount==1,"Show-shot choice performs an actual friend jump");await Task.Delay(Mathf.Max(20,(int)((l.settings.friendReplySeconds+l.settings.jumpSeconds*.5f-l.Flow.Elapsed)*1000)));await Awaitable.EndOfFrameAsync();Check(l.friend.position.y>7.99f,"Friend visibly rises during the jump");await Shot("04_FriendJump");l.Advance(4);await Task.Delay(90);Check(l.Flow.Step==ElevatorStep.Stopped,"Jump branch reaches fault");Check(l.GetComponent<ElevatorCameraEffects>().LastShakeAmplitude>.4f,"Fault starts a decaying camera clunk shake");Check(l.GetComponent<ElevatorCharacterPerformance>().PanicVisible,"Dizzy spiral expression appears after fault");var faceControl=l.GetComponent<ElevatorCharacterPerformance>();Check(faceControl.faceRenderer.sharedMesh==faceControl.panicFaceMesh&&faceControl.panicFaceMesh.triangles.Length<faceControl.normalFaceMesh.triangles.Length,"Original eye and mouth geometry is hidden during panic");Check(!faceControl.panicFace.GetComponentsInChildren<Transform>(true).Any(t=>t.name.Contains("EyeWhite")||t.name.Contains("MouthCover")),"Panic face has no white eyes or mouth covers");Check(faceControl.panicFace.GetComponentsInChildren<LineRenderer>().All(r=>r.sharedMaterial.GetColor("_BaseColor").maxColorComponent<.01f),"Panic expression uses plain black lines");await Shot("05_FaultAndPanicFace");await Task.Delay(900);l.Advance(2);Clear();
   await Physical("3F_Side_Emergency_1.28m");Check(l.Flow.Step==ElevatorStep.Connecting,"Reachable side emergency button connects");l.Advance(4);Clear();l.view.InvokeChoice(0);Check(l.Flow.SituationReported,"Situation reported through original choice");await Physical("3F_LiftIdentity_HB-EL-01");Check(l.Flow.IdentityFound,"Identity plate inspection works");l.view.InvokeChoice(0);l.view.InvokeChoice(0);Check(l.Flow.Step==ElevatorStep.Waiting,"Advice leads to reassuring the friend");l.view.InvokeChoice(0);Check(l.Flow.Step==ElevatorStep.WaitingFade,"Reassuring the friend begins faded waiting");l.Advance(1.5f);await Shot("06_FadedWaiting");Check(faceControl.faceRenderer.sharedMesh==faceControl.normalFaceMesh,"Normal expression returns after reassurance");l.Advance(4);Clear();Check(l.Flow.Step==ElevatorStep.Rescue,"Faded waiting connects to rescue");l.Advance(4);Clear();l.view.InvokeChoice(0);l.Advance(5);Clear();l.view.InvokeChoice(0);l.Advance(4);Clear();l.view.InvokeChoice(0);l.Advance(7);Clear();Check(l.Flow.Step==ElevatorStep.Complete&&l.Floor==1,"Original scenario completes at the 1F exit");await Task.Delay(450);Check(Mathf.Abs(l.playerCamera.transform.position.y-c.eyeHeight)<.08f,"Player remains grounded at completion");await Shot("07_OriginalComplete");
   l.pauseMenu.Pause();Check(l.pauseMenu.IsPaused&&l.pauseMenu.canvas.renderMode==RenderMode.WorldSpace,"Pause menu also remains world space");l.pauseMenu.Resume();l.Restart();Clear();int f=Time.frameCount;await Task.Delay(200);Check(Time.frameCount>f&&f>frame,"Live frames advanced throughout verification");
  }
