  finally{if(l.pauseMenu.IsPaused)l.pauseMenu.Resume();c.enabled=true;if(blocker)Object.DestroyImmediate(blocker);if(blockerMaterial)Object.DestroyImmediate(blockerMaterial);InputSystem.RemoveDevice(mouse);if(enabled)InputSystem.EnableDevice(hardware);hardware?.MakeCurrent();InputSystem.settings=old;Object.Destroy(temp);}
  var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null,passed,checks,error,frameStart=frame,frameEnd=Time.frameCount,state=l.Snapshot()},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(D+"OriginalVerification.json",report);return report;
 }
